from pathlib import Pathimport numpy as npfrom feature_extraction import extract_mfcc# ============================================================# 1. Project folders# ============================================================project_folder = (    Path.home()    / "Desktop"    / "Assessment001")train_folder = (    project_folder    / "data"    / "train")processed_folder = (    project_folder    / "data"    / "processed")processed_folder.mkdir(    parents=True,    exist_ok=True)output_file = (    processed_folder    / "train_mfcc.npz")# ============================================================# 2. Find class folders# ============================================================class_names = sorted([    folder.name    for folder in train_folder.iterdir()    if folder.is_dir()])print()print("==============================")print("Dataset Preparation")print("==============================")print(    "Training folder:")print(    train_folder)print()print(    "Number of classes:",    len(class_names))print(    "Class names:")print(    class_names)# ============================================================# 3. Containers# ============================================================features = []labels = []file_names = []# ============================================================# 4. Extract MFCC from every training WAV file# ============================================================print()print("==============================")print("Extracting MFCC features")print("==============================")for class_index, class_name in enumerate(    class_names):    class_folder = (        train_folder        / class_name    )    wav_files = sorted(        class_folder.glob(            "*.wav"        )    )    print()    print(        class_name,        ":",        len(wav_files),        "files"    )    for wav_file in wav_files:        # ----------------------------------------------------        # Extract formal MFCC        # ----------------------------------------------------        mfcc = extract_mfcc(            wav_file        )        # ----------------------------------------------------        # Store feature        # ----------------------------------------------------        features.append(            mfcc        )        # ----------------------------------------------------        # Store numerical class label        # ----------------------------------------------------        labels.append(            class_index        )        # ----------------------------------------------------        # Store file name        # ----------------------------------------------------        file_names.append(            wav_file.name        )# ============================================================# 5. Convert lists to NumPy arrays# ============================================================X = np.array(    features)y = np.array(    labels,    dtype=np.int64)names = np.array(    class_names)file_names = np.array(    file_names)# ============================================================# 6. Check dataset# ============================================================print()print("==============================")print("Dataset shapes")print("==============================")print(    "X shape:",    X.shape)print(    "y shape:",    y.shape)print(    "names shape:",    names.shape)print(    "file_names shape:",    file_names.shape)print()print(    "Total recordings:",    len(X))print(    "Number of classes:",    len(names))# ============================================================# 7. Show recordings per class# ============================================================print()print("==============================")print("Recordings per class")print("==============================")for class_index, class_name in enumerate(    names):    number_of_recordings = np.sum(        y == class_index    )    print(        class_name,        ":",        number_of_recordings    )# ============================================================# 8. Safety checks# ============================================================if len(class_names) != 20:    print()    print(        "WARNING: Expected 20 classes, "        f"but found {len(class_names)}."    )if len(X) != 400:    print()    print(        "WARNING: Expected 400 recordings, "        f"but found {len(X)}."    )# Check whether all feature matrices have the expected sizeif X.ndim != 3:    raise ValueError(        "X does not have the expected "        "(recordings, frames, coefficients) shape."    )if X.shape[1:] != (199, 13):    print()    print(        "WARNING: Expected each MFCC to have "        "shape (199, 13), but got:",        X.shape[1:]    )# ============================================================# 9. Save processed dataset# ============================================================np.savez(    output_file,    X=X,    y=y,    names=names,    file_names=file_names)# ============================================================# 10. Final summary# ============================================================print()print("==============================")print("Dataset saved successfully!")print("==============================")print(    "Saved to:")print(    output_file)print()print(    "Final X shape:",    X.shape)print(    "Final y shape:",    y.shape)print(    "Number of classes:",    len(names))print(    "Number of file names:",    len(file_names))